"use client";
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {bankBalanceInput} from '@/lib/cashier-bank-close';
import {readBankAccounts} from '@/lib/cashier-bank-deposits';
import {checkDirectDeposit,readDirectDepositReceipt,readDirectDepositStatus,type DirectDepositRequest} from '@/lib/cashier-direct-deposit';
import type {HandoffScope} from '@/lib/cashier-handoff';
export function CashierDirectDeposit({scope,session,onSaved}:{scope:HandoffScope;session:string;onSaved:()=>void}){
 const [banks,setBanks]=useState<ReturnType<typeof readBankAccounts>|null>(null),[available,setAvailable]=useState<string|null>(null),[bank,setBank]=useState(''),[amount,setAmount]=useState(''),[reference,setReference]=useState(''),[date,setDate]=useState(''),[reason,setReason]=useState(''),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[pending,setPending]=useState<DirectDepositRequest|null>(null),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 const alive=useRef(false),lock=useRef(false),key=['irp.direct.deposit.v1',scope.tenant,scope.property,scope.actor,session].join(':');
 useEffect(()=>{alive.current=true;try{const raw=sessionStorage.getItem(key);if(raw){const r=checkDirectDeposit(JSON.parse(raw));if(r.scope.tenant!==scope.tenant||r.scope.property!==scope.property||r.scope.actor!==scope.actor||r.session!==session)throw Error('Saved deposit belongs to another drawer.');setPending(r)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to recover deposit.')}return()=>{alive.current=false}},[key]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen this drawer.');}
 async function run(kind:'load'|'more'|'save'|'check'|'cancel'){
  if(lock.current||!ready)return;lock.current=true;setBusy(true);setError('');setMessage('');
  try{await identify();const args={p_tenant:scope.tenant,p_property:scope.property};
   if(kind==='load'||kind==='more'){
    const cursor=kind==='more'?banks?.next:null;if(kind==='more'&&!cursor)return;
    const accounts=readBankAccounts(await hotelRpc('cashier_bank_accounts',{...args,p_before:cursor??null}),scope,cursor??null);
    const a=await hotelRpc<Record<string,unknown>>('cashier_drawer_available',{...args,p_session:session});
    if(a.schema_version!==1||a.tenant_id!==scope.tenant||a.property_id!==scope.property||a.actor_id!==scope.actor||a.session_id!==session||a.assigned_cashier!==true||a.cashier_paused!==false||typeof a.available_minor!=='string'||! /^\d+$/.test(a.available_minor))throw Error('Drawer is unavailable for a direct deposit.');
    await identify();if(alive.current){setBanks(accounts);setBank('');setAvailable(a.available_minor);setConfirmed(false)}return;
   }
   let r=pending;if(!r){if(kind!=='save'||!confirmed||available===null)throw Error('Review and confirm the deposit.');if(sessionStorage.getItem(key)!==null)throw Error('Recover the saved deposit first.');r=checkDirectDeposit({id:crypto.randomUUID(),scope,session,bank,amount:bankBalanceInput(amount),reference:reference.trim(),date,reason:reason.trim()});if(BigInt(r.amount)>BigInt(available))throw Error('Deposit exceeds available drawer cash.');sessionStorage.setItem(key,JSON.stringify(r));setPending(r)}
   if(kind==='save'){readDirectDepositReceipt(await hotelRpc('declare_direct_cashier_deposit',{...args,p_session:r.session,p_request:r.id,p_bank:r.bank,p_amount:r.amount,p_reference:r.reference,p_date:r.date,p_reason:r.reason,p_confirmed:true}),r)}
   if(kind==='cancel'){if(!cancelConfirmed)throw Error('Confirm cancellation.');await hotelRpc('cancel_cashier_bank_deposit_request',{...args,p_request:r.id,p_confirmed:true})}
   const status=readDirectDepositStatus(await hotelRpc('direct_cashier_deposit_status',{...args,p_request:r.id}),r);await identify();
   if(status.found||status.cancelled){sessionStorage.removeItem(key);if(alive.current){setPending(null);setAvailable(null);setConfirmed(false);setCancelConfirmed(false);setMessage(status.cancelled?'Direct deposit request cancelled.':status.voided?'Direct deposit was recorded and later voided.':'Direct deposit recorded. Bank receipt and accounting still require review.');onSaved()}}else if(alive.current)setMessage('No deposit recorded. Retry or cancel the saved request.');
  }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to complete direct deposit.')}finally{lock.current=false;if(alive.current)setBusy(false)}
 }
 return <section><h3>Deposit directly from this drawer</h3><button type="button" disabled={busy||!!pending||!ready} onClick={()=>void run('load')}>Load drawer cash and banks</button>{available!==null&&<p>Available drawer cash: {usd(Number(available))}</p>}<fieldset disabled={busy||!!pending||!ready}><label>Deposit bank<select value={bank} onChange={e=>{setBank(e.target.value);setConfirmed(false)}}><option value="">Choose bank</option>{banks?.entries.map(b=><option key={b.id} value={b.id}>{b.label}</option>)}</select></label>{banks?.next&&<button type="button" onClick={()=>void run('more')}>More deposit banks</button>}{[['Deposit amount',amount,setAmount,'text'],['Deposit reference',reference,setReference,'text'],['Deposit date',date,setDate,'date'],['Deposit explanation',reason,setReason,'text']].map(([label,value,setter,type])=><label key={label as string}>{label as string}<input type={type as string} value={value as string} onChange={e=>{(setter as (v:string)=>void)(e.target.value);setConfirmed(false)}}/></label>)}</fieldset><label><input type="checkbox" disabled={busy||!ready} checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this direct deposit</label><button type="button" disabled={busy||!ready||!confirmed||(!pending&&(!bank||available===null))} onClick={()=>void run('save')}>{pending?'Retry direct deposit':'Record direct deposit'}</button>{pending&&<><button type="button" disabled={busy} onClick={()=>void run('check')}>Check direct deposit outcome</button><label><input type="checkbox" disabled={busy} checked={cancelConfirmed} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel if not recorded</label><button type="button" disabled={busy||!cancelConfirmed} onClick={()=>void run('cancel')}>Cancel direct deposit request</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
